#include <bits/stdc++.h>
using namespace std;

optional<vector<int>> topological_order(const vector<vector<int>>& adj) {
    int n = static_cast<int>(adj.size()) - 1;
    vector<int> incoming(n + 1);
    for (int vertex = 1; vertex <= n; ++vertex) {
        for (int next : adj[vertex]) {
            ++incoming[next];
        }
    }
    queue<int> ready;
    for (int vertex = 1; vertex <= n; ++vertex) {
        if (incoming[vertex] == 0) {
            ready.push(vertex);
        }
    }

vector<int> order;
while (!ready.empty()) {
    int vertex = ready.front();
    ready.pop();
    order.push_back(vertex);
    for (int next : adj[vertex]) {
        if (--incoming[next] == 0) {
            ready.push(next);
        }
    }
}

    if (static_cast<int>(order.size()) != n) {
        return nullopt;
    }
    return order;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int first, second;
        cin >> first >> second;
        adj[first].push_back(second);
    }
    auto order = topological_order(adj);
    if (!order.has_value()) {
        cout << "IMPOSSIBLE\n";
        return 0;
    }
    for (int i = 0; i < n; ++i) {
        cout << (*order)[i] << (i + 1 == n ? '\n' : ' ');
    }
}

